CustomField.formula:
IF(
OR(

/* Same territory */
Territory__c = $User.TPB_Territory__c,

/* Parent territory (NSM coverage) */
Parent_Territory__c = $User.TPB_Territory__c,

/* Directors (NSD) matching territory prefix */
AND(
    $User.Title = "NSD",
    LEFT($User.Territory_Id__c,2) = LEFT(Territory__c,2)
),

/* Admin override */
$Profile.Name = "System Administrator",

/* Executive role */
$UserRole.Name = "Executive"

),
1,
0
)
